def to_minutes(x):
    if isinstance(x, int):
        return x
    s = str(x).strip()
    ampm = None
    if len(s) >= 2 and s[-2:].upper() in ("AM", "PM"):
        ampm = s[-2:].upper()
        s = s[:-2].strip()
    if ":" in s:
        h, m = s.split(":", 1)
        h = int(h)
        m = int(m)
    else:
        h = int(s)
        m = 0
    if ampm == "PM" and h != 12:
        h += 12
    elif ampm == "AM" and h == 12:
        h = 0
    return h * 60 + m


def fmt(minutes):
    minutes %= 1440
    return f"{minutes // 60:02d}:{minutes % 60:02d}"


def make_interval(wrap):
    def interval(a, b):
        a_raw = to_minutes(a)
        b_raw = to_minutes(b)

        if a_raw == b_raw:
            return set()

        a = a_raw % 1440
        b = b_raw if b_raw == 1440 else b_raw % 1440

        if not wrap:
            # Same-day interval: use the shorter interval between the two endpoints.
            if a > b:
                a, b = b, a
            if a == b:
                return set()
            return set(range(a, b))

        # Text-order interval, allowing wrap-around past midnight.
        if a == b:
            if a_raw == 0 and b_raw == 1440:
                return set(range(1440))
            return set()
        if a < b:
            return set(range(a, b))
        return set(range(a, 1440)) | set(range(0, b))

    return interval


def find_answer(work_minutes, candidates, blocked_sets, duration):
    if duration <= 0:
        for s in candidates:
            if s in work_minutes:
                return (s, s)
        return None

    if duration >= 1440:
        meeting_minutes = set(range(1440))
        if meeting_minutes <= work_minutes and all(not (meeting_minutes & b) for b in blocked_sets):
            for s in candidates:
                return (s, (s + duration) % 1440)
        return None

    for s in candidates:
        meeting_minutes = set((s + i) % 1440 for i in range(duration))
        if meeting_minutes <= work_minutes:
            ok = True
            for b in blocked_sets:
                if meeting_minutes & b:
                    ok = False
                    break
            if ok:
                return (s, (s + duration) % 1440)
    return None


