def parse_time(s):
    s = str(s).strip()
    if ":" not in s:
        return int(s) % 1440
    h, m = s.split(":")
    minutes = int(h) * 60 + int(m)
    if minutes == 1440:
        return 1440
    return minutes % 1440


def fmt_time(m):
    m = int(m) % 1440
    return f"{m // 60:02d}:{m % 60:02d}"


def to_intervals(start, end, full_on_equal=False):
    if start == end:
        return [(0, 1440)] if full_on_equal else []

    if start < end:
        return [(start, end)]

    forward = 1440 - start + end
    backward = start - end

    if forward <= backward:
        intervals = []
        if start < 1440:
            intervals.append((start, 1440))
        if end > 0:
            intervals.append((0, end))
        return intervals

    return [(end, start)]


def point_in_work(t, intervals):
    return any(a <= t < b for a, b in intervals)


def point_free(t, intervals):
    return not any(a <= t < b for a, b in intervals)


def is_valid(start, duration, work_intervals, busy_intervals):
    if duration < 0 or duration > 1440:
        return False

    if duration == 1440:
        segments = [(0, 1440)]
    else:
        end = start + duration
        if end <= 1440:
            segments = [(start, end)]
        else:
            segments = [(start, 1440), (0, end % 1440)]

    for a, b in segments:
        if a >= b:
            continue

        if not any(ws <= a and b <= we for ws, we in work_intervals):
            return False

        for c, d in busy_intervals:
            if a < d and c < b:
                return False

    return True


