    return [(a, b)]


def overlaps(s, e, seg):
    c, d = seg
    if c >= d:
        return False
    return s < d and e > c


def find_candidate(work_segments, busy_segments, dur, pref):
    for a, b in work_segments:
        if b < a:
            continue
        upper = b - dur
        if upper < a:
            continue
        if upper > 1439:
            upper = 1439
        for s in range(a, upper + 1):
            e = s + dur
            if e > 1440:
                continue
            if not pref(s, e):
                continue
            ok = True
            for seg in busy_segments:
                if overlaps(s, e, seg):
                    ok = False
                    break
            if ok:
                return s, e
    return None


