def parse_time(name):
    s = str(VALUES[name]).strip().upper()
    if "AM" in s or "PM" in s:
        ampm = "AM" if "AM" in s else "PM"
        s = s.replace("AM", "").replace("PM", "").strip()
        parts = s.split(":")
        h = int(parts[0])
        m = int(parts[1]) if len(parts) > 1 else 0
        if ampm == "PM" and h != 12:
            h += 12
        elif ampm == "AM" and h == 12:
            h = 0
        return h * 60 + m

    parts = s.split(":")
    h = int(parts[0])
    m = int(parts[1]) if len(parts) > 1 else 0
    return h * 60 + m


def format_time(minutes):
    minutes %= L
    h, m = divmod(minutes, 60)
    return f"{h:02d}:{m:02d}"


def make_segments(start, end):
    if abs(end - start) == L:
        return [(0, L)]

    s = start % L
    e = end % L

    if s == e:
        return []

    if s < e:
        return [(s, e)]

    segments = []
    if s < L:
        segments.append((s, L))
    if e > 0:
        segments.append((0, e))
    return segments


def add_segments(mask, segments):
    for a, b in segments:
        if a < b:
            for t in range(a, b):
                mask[t] = True


def candidate_order(ws_raw, we_raw, work_segments):
    if work_segments == [(0, L)]:
        return list(range(L))

    ws = ws_raw % L
    we = we_raw % L

    if ws == we:
        return []

    if ws < we:
        return list(range(ws, we))

    return list(range(ws, L)) + list(range(0, we))


def solve_circular(duration):
    duration = int(duration)
    if duration < 0:
        duration = -duration

    ws_raw = parse_time("T16")
    we_raw = parse_time("T10")

    work_segments = make_segments(ws_raw, we_raw)
    work_mask = [False] * L
    add_segments(work_mask, work_segments)

    busy_mask = [False] * L
    for a, b in BUSY_PAIRS:
        add_segments(busy_mask, make_segments(parse_time(a), parse_time(b)))

    candidates = candidate_order(ws_raw, we_raw, work_segments)

    if duration == 0:
        for s in candidates:
            if work_mask[s] and not busy_mask[s]:
                return (s, s)
        for s in candidates:
            if work_mask[s]:
                return (s, s)
        return None

    if duration > L:
        if all(work_mask) and not any(busy_mask):
            s = candidates[0] if candidates else 0
            return (s, (s + duration) % L)
        return None

    size = 2 * L
    work2 = [0] * size
    busy2 = [0] * size

    for i in range(size):
        work2[i] = 1 if work_mask[i % L] else 0
        busy2[i] = 1 if busy_mask[i % L] else 0

    pref_work = [0] * (size + 1)
    pref_busy = [0] * (size + 1)

    for i in range(size):
        pref_work[i + 1] = pref_work[i] + work2[i]
        pref_busy[i + 1] = pref_busy[i] + busy2[i]

    for s in candidates:
        if s + duration > size:
            continue
        if (
            pref_work[s + duration] - pref_work[s] == duration
            and pref_busy[s + duration] - pref_busy[s] == 0
        ):
            return (s, (s + duration) % L)

    return None


def solve_linear(duration):
    duration = int(duration)
    if duration < 0:
        duration = -duration

    ws = parse_time("T16")
    we = parse_time("T10")
    if ws > we:
        ws, we = we, ws

    intervals = []
    for a, b in BUSY_PAIRS:
        a = parse_time(a)
        b = parse_time(b)
        if a > b:
            a, b = b, a
        if a < b:
            intervals.append((a, b))

    intervals.sort()
    merged = []

    for a, b in intervals:
        if merged and a <= merged[-1][1]:
            if b > merged[-1][1]:
                merged[-1][1] = b
        else:
            merged.append([a, b])

    if duration == 0:
        for s in range(ws, we + 1):
            if s < 0 or s > L:
                continue
            ok = True
            for a, b in merged:
                if a < s and s < b:
                    ok = False
                    break
            if ok:
                return (s, s)
        return None

    if we - ws < duration:
        return None

    for s in range(ws, we - duration + 1):
        e = s + duration
        ok = True
        for a, b in merged:
            if a < e and s < b:
                ok = False
                break
        if ok:
            return (s, e)

    return None


