def to_min(t):
    parts = str(t).strip().split(":")
    return int(parts[0]) * 60 + int(parts[1])

def fmt(m):
    m %= 1440
    return f"{m // 60:02d}:{m % 60:02d}"

def interval_length(start, end):
    # Times are in minutes, with 1440 allowed as end-of-day.
    if end >= start:
        return end - start
    return 1440 - start + end

