def overlaps(s, e, bs, be):
    m_len = D
    b_len = interval_length(bs, be)
    if m_len == 0 or b_len == 0:
        return False
    return (bs - s) % 1440 < m_len or (s - bs) % 1440 < b_len

def is_free(day, s, e):
