    return (0 - s) % 1440 < D or (s - 0) % 1440 < pref_time

def entirely_before(s, e):
    # Meeting is completely inside the part of the day before T13.
    if D == 0:
        return 0 < pref_time and s < pref_time
    if pref_time >= 1440:
        return True
    if pref_time <= 0:
        return False
    return D <= pref_time and s + D <= pref_time

def strict_pref(day, s, e):
    return not (day == "Day1" and overlaps_before(s, e))

def soft_pref(day, s, e):
    return not (day == "Day1" and entirely_before(s, e))

